using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
public sealed class PreBuildVerification:MonoBehaviour
{
 public string output="Validation/LOGR-playtest.txt";public bool full;
 readonly List<string> lines=new(),errors=new();Keyboard kb;
 public Action<bool> finished;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Initialize(){if(Application.isEditor)return;var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-pre-verify");if(i<0||i+1>=args.Length)return;var go=new GameObject("S4 pre prescribed verification");DontDestroyOnLoad(go);var runner=go.AddComponent<PreBuildVerification>();runner.output=Path.GetFullPath(args[i+1]);runner.full=true;}
 void Check(bool ok,string text){if(!ok)throw new Exception(text);lines.Add("PASS: "+text);}
 void Log(string m,string s,LogType t){if(t is LogType.Error or LogType.Exception or LogType.Assert)errors.Add(m+s);}
 IEnumerator Start(){DontDestroyOnLoad(gameObject);Application.logMessageReceived+=Log;QualitySettings.vSyncCount=0;Application.targetFrameRate=60;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;
 #if UNITY_EDITOR
 InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;
 #endif
 kb=InputSystem.AddDevice<Keyboard>();var stack=new Stack<IEnumerator>();stack.Push(Tests());bool fail=false;while(stack.Count>0&&!fail){object next=null;try{if(!stack.Peek().MoveNext()){stack.Pop();continue;}next=stack.Peek().Current;}catch(Exception e){fail=true;lines.Add(e.ToString());}if(next is IEnumerator child)stack.Push(child);else if(!fail)yield return next;}PlaytestLogger.Instance?.Finish();Application.logMessageReceived-=Log;InputSystem.RemoveDevice(kb);fail|=errors.Count>0;lines.AddRange(errors);lines.Insert(0,(fail?"FAIL":"PASS")+(full?" S4-pre actual exe":" LOGR Editor"));lines.Add("Error/Exception/Assert="+errors.Count);File.WriteAllLines(output,lines);if(finished!=null)finished(!fail);else Application.Quit(fail?1:0);}
 IEnumerator Until(Func<bool> test,float seconds=8){double end=Time.realtimeSinceStartupAsDouble+seconds;while(!test()){if(Time.realtimeSinceStartupAsDouble>end)throw new Exception("Pre verification timeout");yield return null;}}
 IEnumerator Keys(params Key[] keys){InputSystem.QueueStateEvent(kb,new KeyboardState(keys));yield return null;yield return new WaitForSecondsRealtime(.03f);}
 IEnumerator Ready(){yield return Until(()=>RoomSession.Instance?.Player!=null&&!RoomSession.Instance.Transitioning&&!RoomSession.Instance.Respawning);yield return new WaitForSeconds(.2f);}
 void Place(Vector2 at){var player=RoomSession.Instance.Player;player.ClearTransientInput();player.transform.position=at;var body=player.GetComponent<Rigidbody2D>();body.position=at;body.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();}
 string Hash(){using var sha=SHA256.Create();return Convert.ToBase64String(sha.ComputeHash(File.ReadAllBytes(ProgressSave.FilePath)));}
 IEnumerator Door(string target){var exit=Array.Find(FindObjectsByType<RoomExit>(FindObjectsSortMode.None),e=>e.destinationRoomId==target);Check(exit!=null&&exit.enabled,"door "+target);Place(exit.transform.position);yield return new WaitForFixedUpdate();yield return Until(()=>RoomSession.Instance.CurrentRoomId==target&&!RoomSession.Instance.Transitioning);yield return Ready();}
 IEnumerator Tests(){yield return new WaitForSecondsRealtime(.3f);var menu=FindFirstObjectByType<SaveMenu>();Check(menu!=null&&!PlaytestLogger.Instance.Recording,"Menu logging inactive before new game");if(menu.Selection==0){yield return Keys(Key.DownArrow);yield return Keys();}yield return Keys(Key.Z);yield return Keys();if(FindFirstObjectByType<SaveMenu>()?.Confirming==true){yield return Keys(Key.Z);yield return Keys();}yield return Ready();yield return Until(()=>PlaytestLogger.Instance.Recording);var logger=PlaytestLogger.Instance;Check(File.Exists(logger.CsvPath),"new game CSV created "+logger.CsvPath);Check(RoomSession.Instance.CurrentRoomId=="A01","new game A01");
 if(full){var fx=RoomSession.Instance.Player.GetComponent<AttackFeedback>();if(fx!=null){int count=fx.Activations;Place(new Vector2(8,1.81f));yield return Keys(Key.X);yield return Keys();yield return new WaitForSeconds(.2f);Check(fx.Activations>count,"A01 AttackSlash activation");}}
 string before=Hash();yield return Door("A02");Place(new Vector2(8,1.81f));Vector2 deathPosition=RoomSession.Instance.Player.transform.position;Check(RoomSession.Instance.Die(),"one death requested in A02");yield return Until(()=>RoomSession.Instance.Respawning);yield return Until(()=>!RoomSession.Instance.Respawning);yield return Ready();Check(Hash()==before,"ProgressSave SHA256 unchanged through room/death test");double active=logger.ActiveSeconds,pause=logger.PauseSeconds;RoomSession.Instance.Player.SetPaused(true);yield return new WaitForSecondsRealtime(3);RoomSession.Instance.Player.SetPaused(false);Check(logger.PauseSeconds-pause>=2.95&&logger.PauseSeconds-pause<=3.15&&logger.ActiveSeconds-active<.12,"Pause ~3s excluded from active elapsed");Check(Hash()==before,"ProgressSave SHA256 unchanged after Pause");string csv=File.ReadAllText(logger.CsvPath);Check(csv.Contains("\"room_enter\",\"A02\"")&&csv.Contains("\"death\",\"A02\",8.000000,1.810000,\"unrecorded\"")&&csv.Contains("\"pause_start\"")&&csv.Contains("\"pause_end\""),"CSV room/death exact location/unrecorded/Pause rows");lines.Add($"MEASURE death={deathPosition} active={logger.ActiveSeconds:F6} pause={logger.PauseSeconds:F6}; hash={before}");
 if(full){yield return Door("A02");yield return Door("A03");yield return Door("A04");var enemy=FindFirstObjectByType<EnemyPatrol>();if(enemy.GetComponent<HitFeedback>()!=null){int calls=enemy.GetComponent<HitFeedback>().Calls;enemy.ReceiveHit(1,RoomSession.Instance.Player.transform.position);Check(enemy.GetComponent<HitFeedback>().Calls==calls+1,"actual exe enemy HitFeedback event");}Check(RoomSession.Instance.RequestTransition("C04","Assets/Scenes/C04.unity","FromLeft"),"direct C04 setup");yield return Until(()=>RoomSession.Instance.CurrentRoomId=="C04"&&!RoomSession.Instance.Transitioning);yield return Ready();yield return Door("C06");Place(new Vector2(8,1.81f));var boss=FindFirstObjectByType<BossEncounter>();yield return Until(()=>boss.Fighting);yield return null;boss.ReceiveHit(20,RoomSession.Instance.Player.transform.position);yield return Until(()=>FindFirstObjectByType<EndingMenu>()!=null);Check(File.ReadAllText(logger.CsvPath).Contains("\"boss_defeated\"")&&File.ReadAllText(logger.CsvPath).Contains("\"ending\""),"CSV boss defeat / Ending summary");yield return Keys(Key.Z);yield return Keys();yield return Until(()=>FindFirstObjectByType<SaveMenu>()!=null);Check(true,"Ending returns title");}
 else{logger.Finish();csv=File.ReadAllText(logger.CsvPath);Check(csv.Contains("\"summary_region\"")&&csv.Contains("\"summary_deaths\",\"A02\"")&&csv.Contains("\"summary_boss_attempts\""),"summary rows");}
 }
}
